const body = $('Webhook').first().json.body ?? {};
const existing = $input.all().filter((i) => i.json && i.json.id);

const system = [
  'You qualify inbound leads for Northstar Digital, an agency selling AI workflow automation, custom web apps, websites, and support retainers.',
  'Return JSON matching the schema exactly.',
  'Score 0-100: service fit (0-40), budget (0-30), urgency (0-15), message quality (0-15).',
  'estimated_budget_usd is a single USD number (midpoint of a range) or 0 if unknown.',
  'suggested_reply_body starts with "Hi <first name>," has no signature and stays under 120 words.'
].join('\n');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['service_category','intent','urgency','estimated_budget_usd','score','confidence','summary','key_signals','risks','recommended_next_step','suggested_reply_subject','suggested_reply_body'],
  properties: {
    service_category: { type: 'string', enum: ['ai_automation','web_app','website','support_maintenance','consulting','other'] },
    intent: { type: 'string', enum: ['ready_to_buy','evaluating','exploring','support_request'] },
    urgency: { type: 'string', enum: ['low','medium','high'] },
    estimated_budget_usd: { type: 'number' },
    score: { type: 'integer' },
    confidence: { type: 'number' },
    summary: { type: 'string' },
    key_signals: { type: 'array', items: { type: 'string' } },
    risks: { type: 'array', items: { type: 'string' } },
    recommended_next_step: { type: 'string' },
    suggested_reply_subject: { type: 'string' },
    suggested_reply_body: { type: 'string' }
  }
};

return [{
  json: {
    lead: body,
    is_repeat_submission: existing.length > 0,
    request: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: JSON.stringify(body) }
      ],
      response_format: { type: 'json_schema', json_schema: { name: 'lead_analysis', strict: true, schema } }
    }
  }
}];

const lead = $('Build AI Prompt').first().json.lead;
const isRepeat = $('Build AI Prompt').first().json.is_repeat_submission;

let a;
let source = 'openai';
try {
  a = JSON.parse($json.choices[0].message.content);
} catch (e) {
  source = 'fallback';
  a = {
    service_category: 'other', intent: 'exploring', urgency: 'low',
    estimated_budget_usd: 0, score: 40, confidence: 0,
    summary: 'AI analysis unavailable. Routed with a neutral score.',
    key_signals: [], risks: ['AI analysis failed'],
    recommended_next_step: 'Review manually.',
    suggested_reply_subject: 'Re: your enquiry to Northstar Digital',
    suggested_reply_body: 'Hi ' + String(lead.full_name || '').split(' ')[0] + ',\n\nThanks for reaching out. We will review your message and reply shortly.'
  };
}

let tier = 'low';
let rule = 'Score below 40';
if (a.score >= 75) { tier = 'high'; rule = 'Score 75 or higher'; }
else if (a.service_category === 'ai_automation' && a.estimated_budget_usd >= 10000) { tier = 'high'; rule = 'AI automation with budget of 10,000 or more'; }
else if (a.service_category === 'support_maintenance' && a.estimated_budget_usd < 2500) { tier = 'low'; rule = 'Support request under 2,500'; }
else if (a.score >= 40) { tier = 'mid'; rule = 'Score between 40 and 74'; }

return [{ json: { lead, analysis: a, analysis_source: source, is_repeat_submission: isRepeat, tier, tier_rule: rule } }];

const d = $json;
const repLine = d.assigned_name + ', ' + d.assigned_role;

const slack = {
  channel: d.slack_channel,
  mock: true,
  text: 'New ' + d.tier + '-tier lead for ' + d.assigned_name + ': ' + d.lead.full_name + (d.lead.company ? ' (' + d.lead.company + ')' : ''),
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: 'New ' + d.tier + '-tier lead' } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Score*\n' + d.analysis.score + '/100' },
      { type: 'mrkdwn', text: '*Assigned to*\n' + d.assigned_name },
      { type: 'mrkdwn', text: '*Category*\n' + d.analysis.service_category },
      { type: 'mrkdwn', text: '*Urgency*\n' + d.analysis.urgency }
    ]},
    { type: 'section', text: { type: 'mrkdwn', text: d.analysis.summary } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Rule: ' + d.tier_rule }] }
  ]
};

const email = {
  mock: true,
  to: d.lead.email,
  from: d.assigned_email,
  subject: d.analysis.suggested_reply_subject,
  body: d.analysis.suggested_reply_body + '\n\n' + repLine + ', Northstar Digital'
};

return [{ json: {
  ok: true,
  tier: d.tier,
  score: d.analysis.score,
  assigned_to: d.assigned_name,
  analysis_source: d.analysis_source,
  is_repeat_submission: d.is_repeat_submission,
  slack_message: slack,
  email_draft: email
}}];
